CREATE TABLE workspace_permission_versions(workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id),version INTEGER NOT NULL DEFAULT 1);
INSERT INTO workspace_permission_versions(workspace_id) SELECT id FROM workspaces;
CREATE TRIGGER cp6_workspace_created AFTER INSERT ON workspaces BEGIN INSERT INTO workspace_permission_versions(workspace_id) VALUES (NEW.id); END;
CREATE TRIGGER cp6_assignment_insert AFTER INSERT ON workspace_memberships BEGIN UPDATE workspace_permission_versions SET version=version+1 WHERE workspace_id=NEW.workspace_id; END;
CREATE TRIGGER cp6_assignment_update AFTER UPDATE ON workspace_memberships BEGIN UPDATE workspace_permission_versions SET version=version+1 WHERE workspace_id=NEW.workspace_id; END;
CREATE TRIGGER cp6_assignment_delete AFTER DELETE ON workspace_memberships BEGIN UPDATE workspace_permission_versions SET version=version+1 WHERE workspace_id=OLD.workspace_id; END;
CREATE TRIGGER cp6_membership_update AFTER UPDATE ON memberships BEGIN UPDATE workspace_permission_versions SET version=version+1 WHERE workspace_id IN (SELECT id FROM workspaces WHERE organization_id=NEW.organization_id); END;
CREATE TRIGGER cp6_membership_delete AFTER DELETE ON memberships BEGIN UPDATE workspace_permission_versions SET version=version+1 WHERE workspace_id IN (SELECT id FROM workspaces WHERE organization_id=OLD.organization_id); END;
CREATE TABLE database_write_access(database_id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),enabled INTEGER NOT NULL CHECK(enabled IN (0,1)),revision INTEGER NOT NULL DEFAULT 1,approved_by TEXT NOT NULL REFERENCES users(id),updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE sql_approvals(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),workspace_id TEXT NOT NULL REFERENCES workspaces(id),database_id TEXT NOT NULL,sql_digest TEXT NOT NULL,context_digest TEXT NOT NULL,permission_version INTEGER NOT NULL,access_revision INTEGER NOT NULL,expires_at INTEGER NOT NULL,consumed_at INTEGER);
CREATE TABLE sql_executions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),workspace_id TEXT NOT NULL REFERENCES workspaces(id),database_id TEXT NOT NULL,sql_digest TEXT NOT NULL,operation TEXT NOT NULL,risk TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('executing','committed','failed','unknown')),affected_rows INTEGER,error_code TEXT,created_at TEXT NOT NULL DEFAULT (datetime('now')),finished_at TEXT);
CREATE INDEX idx_sql_history ON sql_executions(workspace_id,user_id,created_at);
CREATE TRIGGER cp6_user_update AFTER UPDATE ON users BEGIN UPDATE workspace_permission_versions SET version=version+1 WHERE workspace_id IN (SELECT w.id FROM workspaces w JOIN memberships m ON m.organization_id=w.organization_id WHERE m.user_id=NEW.id); END;
CREATE TRIGGER cp6_organization_update AFTER UPDATE ON organizations BEGIN UPDATE workspace_permission_versions SET version=version+1 WHERE workspace_id IN (SELECT id FROM workspaces WHERE organization_id=NEW.id); END;
